// Rotatie van order B (EUR 250). Startmaand: oktober 2026 = index 0.
// Augustus en september zijn inhaalmaanden (index 10 en 11).
const rotatie = [
  { naam: 'Rheinmetall', ticker: 'RHM', beurs: 'Xetra', valuta: 'EUR', opmerking: 'Fractie-order: bedrag EUR 250 invullen.' },
  { naam: 'ASML', ticker: 'ASML', beurs: 'Euronext Amsterdam', valuta: 'EUR', opmerking: 'Fractie-order: bedrag EUR 250 invullen.' },
  { naam: 'iShares MSCI China UCITS ETF', ticker: 'ICGA', beurs: 'Xetra', valuta: 'EUR', opmerking: 'Gebruik gratis ETF-order nummer 2.' },
  { naam: 'Fortum', ticker: 'FORTUM', beurs: 'Nasdaq Helsinki', valuta: 'EUR', opmerking: 'Hele stukken, ca. 10.' },
  { naam: 'Saab B', ticker: 'SAAB B', beurs: 'Nasdaq Stockholm', valuta: 'SEK', opmerking: 'EERST EUR 250 naar SEK wisselen. Let op: B-aandeel.' },
  { naam: 'Cameco', ticker: 'CCJ', beurs: 'NYSE', valuta: 'USD', opmerking: 'EERST EUR 250 naar USD wisselen.' },
  { naam: 'Thales', ticker: 'HO', beurs: 'Euronext Paris', valuta: 'EUR', opmerking: '1 stuk.' },
  { naam: 'Rolls-Royce', ticker: 'RR', beurs: 'London Stock Exchange', valuta: 'GBP', opmerking: 'EERST EUR 250 naar GBP wisselen. Koers in pence: 1100p = GBP 11.' },
  { naam: 'Schneider Electric', ticker: 'SU', beurs: 'Euronext Paris', valuta: 'EUR', opmerking: '1 stuk.' },
  { naam: 'Broadcom', ticker: 'AVGO', beurs: 'Nasdaq', valuta: 'USD', opmerking: 'Fractie-order. EERST EUR 250 naar USD wisselen.' },
  { naam: 'INHAALMAAND', ticker: '-', beurs: '-', valuta: '-', opmerking: 'Koop de naam die het verst onder 10% van de satelliet zit.' },
  { naam: 'INHAALMAAND + JAARLIJKSE EVALUATIE', ticker: '-', beurs: '-', valuta: '-', opmerking: 'Zie hoofdstuk 16.5 van het rapport. Vergelijk satelliet met IWDA.' },
];

const start = new Date(2026, 9, 1); // oktober 2026
const nu = new Date();
const maandenSindsStart = (nu.getFullYear() - start.getFullYear()) * 12 + (nu.getMonth() - start.getMonth());
const index = ((maandenSindsStart % 12) + 12) % 12;
const cyclus = Math.floor(maandenSindsStart / 12) + 1;
const b = rotatie[index];

const maandNaam = nu.toLocaleDateString('nl-NL', { month: 'long', year: 'numeric' });

const regels = [
  'Tijd: tussen 16:00 en 17:15.',
  'Ordertype: LIMIT op de midprijs. Geldigheid: Day. Nooit een marktorder.',
  'Niet gevuld om 17:15? Limiet op de laatprijs. Niet gevuld bij sluiting? Morgen opnieuw.',
  'Zelfde bedrag, zelfde dag, ook bij -30%. De rotatie beslist, niet jij.',
  'Noteer datum, naam, aantal, koers en bedrag in het logboek.',
];

const tekst = [
  `Kooporders ${maandNaam} (cyclus ${cyclus})`,
  '',
  'ORDER A (gratis ETF-order 1)',
  'IWDA, Euronext Amsterdam, EUR 500, limiet op midprijs.',
  '',
  'ORDER B (EUR 250)',
  `${b.naam}`,
  `Ticker: ${b.ticker} | Beurs: ${b.beurs} | Valuta: ${b.valuta}`,
  `${b.opmerking}`,
  '',
  'CHECKLIST',
  ...regels.map((r, i) => `${i + 1}. ${r}`),
].join('\n');

return [{ json: { tekst, orderB: b, index, cyclus, maand: maandNaam } }];
